namespace sv_65cc402500b64e9cb0f620ba5b9e51c8.Services;

public class WarehouseState
{
    public string CurrentWarehouseId { get; private set; } = "warehouse-a";
    public string CurrentWarehouseName => Warehouses.TryGetValue(CurrentWarehouseId, out var name) ? name : "Unknown";

    public static readonly Dictionary<string, string> Warehouses = new()
    {
        ["warehouse-a"] = "Warehouse A — Downtown",
        ["warehouse-b"] = "Warehouse B — Airport",
        ["warehouse-c"] = "Warehouse C — Harbor"
    };

    public event Func<Task>? OnChange;

    public async Task SetWarehouseAsync(string warehouseId)
    {
        if (CurrentWarehouseId == warehouseId) return;
        CurrentWarehouseId = warehouseId;
        if (OnChange is not null)
            await OnChange.Invoke();
    }
}

namespace sv_65cc402500b64e9cb0f620ba5b9e51c8.Services;

public class InventoryAlertService
{
    private readonly Random _random = new();

    public int CurrentLowStockCount { get; private set; }

    public event Func<Task>? OnAlertCountChanged;

    /// <summary>
    /// Simulates a database query returning items below minimum stock levels.
    /// </summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        // Simulate latency-free DB call returning random count 0–15
        return Task.FromResult(_random.Next(0, 16));
    }

    /// <summary>
    /// Fetches the latest count and notifies all subscribers if it changed.
    /// </summary>
    public async Task RefreshAsync(string warehouseId)
    {
        CurrentLowStockCount = await GetLowStockCountAsync(warehouseId);
        if (OnAlertCountChanged is not null)
            await OnAlertCountChanged.Invoke();
    }
}

