@page "/dashboard"
@using sv_65cc402500b64e9cb0f620ba5b9e51c8.Services
@inject WarehouseState WarehouseState
@inject InventoryAlertService AlertService
@implements IDisposable
@rendermode InteractiveServer

<PageTitle>Dashboard — @WarehouseState.CurrentWarehouseName</PageTitle>

<h1>Warehouse Dashboard</h1>
<p class="text-muted">Viewing: <strong>@WarehouseState.CurrentWarehouseName</strong></p>

<div class="card mt-3" style="max-width: 400px;">
    <div class="card-body">
        <h5 class="card-title">Low-Stock Alerts</h5>
        <p class="display-4">
            @AlertService.CurrentLowStockCount
            <small class="fs-6 text-muted">items below minimum</small>
        </p>
        <p class="text-muted"><small>Auto-refreshes every 10 seconds</small></p>
    </div>
</div>

@code {
    private PeriodicTimer? _timer;
    private CancellationTokenSource? _cts;
    private Func<Task>? _alertHandler;
    private Func<Task>? _warehouseHandler;

    protected override void OnInitialized()
    {
        _alertHandler = () => InvokeAsync(StateHasChanged);
        _warehouseHandler = async () =>
        {
            // When warehouse changes, immediately refresh alerts
            await AlertService.RefreshAsync(WarehouseState.CurrentWarehouseId);
            await InvokeAsync(StateHasChanged);
        };

        AlertService.OnAlertCountChanged += _alertHandler;
        WarehouseState.OnChange += _warehouseHandler;
    }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            // Initial fetch
            await AlertService.RefreshAsync(WarehouseState.CurrentWarehouseId);
            StateHasChanged();

            // Start polling
            _cts = new CancellationTokenSource();
            _timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
            _ = PollAsync(_cts.Token);
        }
    }

    private async Task PollAsync(CancellationToken ct)
    {
        try
        {
            while (await _timer!.WaitForNextTickAsync(ct))
            {
                await AlertService.RefreshAsync(WarehouseState.CurrentWarehouseId);
                // No need to call StateHasChanged here — the event handler does it
            }
        }
        catch (OperationCanceledException) { }
    }

    public void Dispose()
    {
        AlertService.OnAlertCountChanged -= _alertHandler;
        WarehouseState.OnChange -= _warehouseHandler;
        _cts?.Cancel();
        _cts?.Dispose();
        _timer?.Dispose();
    }
}

