@code {
    private PeriodicTimer? _timer;
    private CancellationTokenSource? _cts;
    private Func<Task>? _alertHandler;
    private Func<Task>? _warehouseHandler;

    protected override void OnInitialized()
    {
        _alertHandler = () => InvokeAsync(StateHasChanged);
        _warehouseHandler = async () =>
        {
            // When warehouse changes, immediately refresh alerts
            await AlertService.RefreshAsync(WarehouseState.CurrentWarehouseId);
            await InvokeAsync(StateHasChanged);
        };

        AlertService.OnAlertCountChanged += _alertHandler;
        WarehouseState.OnChange += _warehouseHandler;
    }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            // Initial fetch
            await AlertService.RefreshAsync(WarehouseState.CurrentWarehouseId);
            StateHasChanged();

            // Start polling
            _cts = new CancellationTokenSource();
            _timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
            _ = PollAsync(_cts.Token);
        }
    }

    private async Task PollAsync(CancellationToken ct)
    {
        try
        {
            while (await _timer!.WaitForNextTickAsync(ct))
            {
                await AlertService.RefreshAsync(WarehouseState.CurrentWarehouseId);
                // No need to call StateHasChanged here — the event handler does it
            }
        }
        catch (OperationCanceledException) { }
    }

    public void Dispose()
    {
        AlertService.OnAlertCountChanged -= _alertHandler;
        WarehouseState.OnChange -= _warehouseHandler;
        _cts?.Cancel();
        _cts?.Dispose();
        _timer?.Dispose();
    }
}

